import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {Ajv} from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('throws Unknown tool: <name> for an unregistered name', async () => {
      const registry = new ToolRegistry();
      await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
    });

    it('unit test rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      const definition: ToolDefinition = {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      };
      registry.register(definition, async () => {
        executorCalls += 1;
        return 'sunny';
      });

      const response = await registry.execute('get_weather', {});

      expect({calls: executorCalls, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringMatching(/required.*location|missingProperty.*location|location.*required/i),
      });
    });

    it('passes valid input with an unlisted extra property to the executor unchanged', async () => {
      const registry = new ToolRegistry();
      let capturedInput: Record<string, unknown> | undefined;
      let calls = 0;
      registry.register(
        {
          name: 'test_extra',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {a: {type: 'string'}},
          },
        },
        async input => {
          calls++;
          capturedInput = input;
          return 'ok';
        }
      );
      const input = {a: 'val', extra: 123};
      await registry.execute('test_extra', input);
      expect({calls, capturedInput}).toEqual({calls: 1, capturedInput: input});
    });

    it('rejects a wrong-typed field with a message naming the field path and the expected type, and that the message does not contain the offending value', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test_type',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
          },
        },
        async () => 'ok'
      );

      const response = await registry.execute('test_type', {location: 123456789});
      expect({
        hasLocation: /location/.test(response.result),
        hasString: /string/.test(response.result),
        lacksValue: !/123456789/.test(response.result),
      }).toEqual({hasLocation: true, hasString: true, lacksValue: true});
    });

    it('throws at registration time for an uncompilable schema naming the tool', () => {
      const registry = new ToolRegistry();
      expect(() => {
        registry.register(
          {
            name: 'broken_tool',
            description: 'test',
            inputSchema: {
              type: 'object',
              properties: {a: {type: 'not-a-type'}},
            },
          },
          async () => 'ok'
        );
      }).toThrow(/broken_tool/);
    });

    it('validates a function-valued tool definition against the schema current at that call, not a stale cached one', async () => {
      const registry = new ToolRegistry();
      let schemaRef: Record<string, unknown> = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
      registry.register(
        () => ({
          name: 'dynamic',
          description: 'test',
          inputSchema: schemaRef,
        }),
        async () => 'ok'
      );

      const res1 = await registry.execute('dynamic', {a: 'val'});
      schemaRef = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
      const res2 = await registry.execute('dynamic', {a: 'val'});
      expect({
        res1: res1.result,
        res2Matches: /Validation failed.*b/.test(res2.result),
      }).toEqual({res1: 'ok', res2Matches: true});
    });

    it("compiles a static tool's schema once at registration time", () => {
      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'static_tool_reg',
          description: 'test',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      expect(compileSpy).toHaveBeenCalledTimes(1);
      compileSpy.mockRestore();
    });

    it("does not recompile a static tool's schema across ten execute calls", async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'static_tool_exec',
          description: 'test',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      for (let i = 0; i < 10; i++) {
        await registry.execute('static_tool_exec', {a: 'test'});
      }
      expect(compileSpy).not.toHaveBeenCalled();
      compileSpy.mockRestore();
    });
